// ---- lib/crop.js ----
/**
 * Crop geometry. Pure functions — no DOM, no state.
 *
 * The crop is modelled as a zoom factor plus a centre point in normalised
 * source coordinates, rather than as a pixel rectangle. That way it survives a
 * change of print size: the frame's aspect ratio changes, the customer's
 * intent (what they centred on, how tight they zoomed) does not.
 *
 * Nothing here re-encodes an image. The output is always a rectangle in SOURCE
 * PIXEL coordinates, which travels with the order so the workshop prints from
 * the original file.
 */

const MAX_ZOOM = 4;

const clamp = (v, lo, hi) => Math.min(Math.max(v, lo), hi);

/** Largest rectangle of `aspect` (w/h) that fits inside the source image. */
function coverCrop(pixels, aspect) {
  const imgAspect = pixels.width / pixels.height;
  return imgAspect > aspect
    ? { w: pixels.height * aspect, h: pixels.height }   // source wider: trim the sides
    : { w: pixels.width, h: pixels.width / aspect };    // source taller: trim top and bottom
}

/** Crop size at a given zoom. Zoom 1 is the cover fit; higher is tighter. */
function cropSize(pixels, aspect, zoom) {
  const cover = coverCrop(pixels, aspect);
  const z = clamp(zoom, 1, MAX_ZOOM);
  return { w: cover.w / z, h: cover.h / z };
}

/** Keep a centre point within the range that yields an in-bounds rectangle. */
function clampCentre(pixels, aspect, zoom, centre) {
  const { w, h } = cropSize(pixels, aspect, zoom);
  const halfU = w / 2 / pixels.width;
  const halfV = h / 2 / pixels.height;
  return {
    u: clamp(centre.u, halfU, 1 - halfU),
    v: clamp(centre.v, halfV, 1 - halfV),
  };
}

/** The crop rectangle, in source pixels. */
function cropRect(pixels, aspect, zoom, centre) {
  const { w, h } = cropSize(pixels, aspect, zoom);
  const c = clampCentre(pixels, aspect, zoom, centre);
  return {
    x: clamp(c.u * pixels.width - w / 2, 0, pixels.width - w),
    y: clamp(c.v * pixels.height - h / 2, 0, pixels.height - h),
    w,
    h,
  };
}

/**
 * The same rectangle in whole pixels, for the workshop to cut and print from.
 *
 * On screen the rectangle is fractional, because it follows a zoom slider. A
 * cutting instruction can't be: it is rounded outwards to keep everything the
 * customer framed, then pulled back inside the image so the rectangle it names
 * really exists.
 */
function wholePixelCrop(rect, pixels) {
  if (!rect || !pixels) return null;
  const x = Math.max(0, Math.floor(rect.x));
  const y = Math.max(0, Math.floor(rect.y));
  return {
    x,
    y,
    w: Math.min(Math.ceil(rect.w), pixels.width - x),
    h: Math.min(Math.ceil(rect.h), pixels.height - y),
  };
}

/**
 * Zoom while holding one point still — the point under the cursor, given as a
 * fraction of the displayed opening. Without this, zooming drifts away from
 * whatever the customer was looking at.
 */
function zoomAnchored(pixels, aspect, zoom, centre, anchorX, anchorY, nextZoom) {
  const before = cropRect(pixels, aspect, zoom, centre);
  const sx = before.x + anchorX * before.w;
  const sy = before.y + anchorY * before.h;

  const z = clamp(nextZoom, 1, MAX_ZOOM);
  const { w, h } = cropSize(pixels, aspect, z);

  return {
    zoom: z,
    centre: clampCentre(pixels, aspect, z, {
      u: (sx - anchorX * w + w / 2) / pixels.width,
      v: (sy - anchorY * h + h / 2) / pixels.height,
    }),
  };
}

/** Move the crop by a screen-space delta, converted back to source pixels. */
function panBy(pixels, aspect, zoom, centre, dxScreen, dyScreen, displayedWidth) {
  const rect = cropRect(pixels, aspect, zoom, centre);
  const scale = displayedWidth / rect.w;
  // Dragging the photo right reveals more of its left-hand side, hence the sign.
  return clampCentre(pixels, aspect, zoom, {
    u: (rect.x - dxScreen / scale + rect.w / 2) / pixels.width,
    v: (rect.y - dyScreen / scale + rect.h / 2) / pixels.height,
  });
}


// ---- lib/session.js ----
/**
 * Keeping the customer's place.
 *
 * Wix re-applies attributes by rebuilding the element, and on some pages that
 * goes as far as re-running the script. Either way the configurator can find
 * itself constructed from scratch halfway through an order, and a customer who
 * has chosen a frame, a mount and a size should not be dropped back at "what
 * are you framing?" because the page code answered a question.
 *
 * So the session is written to sessionStorage, which survives both. Everything
 * here is JSON: the File the customer picked cannot be, so only its name and
 * size are kept, enough to tell them it needs picking again.
 *
 * Pure, and defensive: storage can be full, blocked, or hold something written
 * by an older version of this file, and none of that may break the page.
 */

const SESSION_KEY = 'picframing.configurator.v1';

/** What is worth carrying across a rebuild. Anything else is derived or redrawn. */
const PERSISTED = [
  'lane', 'printedByUs', 'pixels', 'sizeId', 'artWidthMm', 'artHeightMm',
  'mouldingCode', 'matStyle', 'mat1Code', 'mat2Code', 'matBorderSidesMm',
  'bottomWeighted', 'rushOrder', 'glazingCode', 'mountingId', 'printPaperCode',
  'deliveryId', 'cropZoom', 'cropCenter', 'photoConsent', 'contact', 'contactOpen',
  'uploadUrls', 'uploadAsked', 'uploaded', 'fileMeta',
];

/** The state, minus anything that can't be written down. */
function packSession(state) {
  const packed = {};
  for (const key of PERSISTED) if (state[key] !== undefined) packed[key] = state[key];
  // The File itself can't be stored, so remember enough to ask for it again.
  if (state.file && !packed.fileMeta) {
    packed.fileMeta = { name: state.file.name, sizeBytes: state.file.size, type: state.file.type };
  }
  return packed;
}

/**
 * Merge a stored session onto a fresh one. Unknown keys are dropped, so a
 * session written by an older build can't put this one into a shape it doesn't
 * expect, and a half-written session simply loses the keys it never got to.
 */
function unpackSession(stored, fresh) {
  const state = { ...fresh };
  if (!stored || typeof stored !== 'object') return state;
  for (const key of PERSISTED) {
    if (stored[key] !== undefined && stored[key] !== null) state[key] = stored[key];
  }
  // One exception to "skip nulls": having already asked for an upload URL and
  // been told no is worth remembering, and it is stored as false.
  if (stored.uploadAsked !== undefined) state.uploadAsked = stored.uploadAsked === true;
  // A photo was chosen before the rebuild, but the file itself didn't survive.
  state.file = null;
  state.imageUrl = null;
  state.submitting = false;
  return state;
}

/** True when the customer had a photo, hasn't uploaded it yet, and we've lost it. */
function photoNeedsPicking(state) {
  return Boolean(state.fileMeta) && !state.file && !state.uploaded;
}

function saveSession(state, storage) {
  try {
    storage?.setItem(SESSION_KEY, JSON.stringify(packSession(state)));
  } catch {
    // Private browsing, a full quota, or storage switched off. The order still
    // works; it just won't survive a rebuild.
  }
}

function loadSession(storage) {
  try {
    const raw = storage?.getItem(SESSION_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

function clearSession(storage) {
  try {
    storage?.removeItem(SESSION_KEY);
  } catch {
    // Nothing to do: a session we can't clear is one we also can't read back.
  }
}


// ---- lib/pricing.js ----
/**
 * Picframing frame configurator — pricing engine.
 *
 * Mirrors how the shop already prices by hand in PriceMaster, derived from 13
 * of their own quotes (test/fixtures/pricemaster-quotes.json):
 *
 *   board    = art + 2 x border          (mount border, or float border)
 *   frame m  = board perimeter + 8 x face width
 *
 *   price    = frame metres x rate per m
 *            + board m² x mount rate     (per mount board)
 *            + board m² x glass rate     (twice over when floating: glass both sides)
 *            + board m² x backing rate   (plain, pasted, or floating)
 *            + a flat fitting charge
 *            + delivery, if any
 *            then 15% VAT, unrounded
 *
 * There are deliberately no separate charges for mat cutting, assembly size
 * bands, hardware or packaging: PriceMaster doesn't have them, and adding them
 * put us 15-40% over the shop's own invoices.
 *
 * Pure functions only: no DOM, no Wix APIs, no network. build.mjs copies this
 * into the Velo backend so the server can re-price requests.
 *
 * All dimensions in MILLIMETRES. All money in ZAR, excluding VAT until the end.
 */

const MM_PER_INCH = 25.4;
const MAT_COUNT = { none: 0, single: 1, double: 2 };

/* ------------------------------------------------------------------ *
 * Geometry
 *
 * Naming, front to back:
 *   art      the printed / supplied piece
 *   opening  the hole cut in the mat; smaller than the art so it cannot fall through
 *   sight    what you actually see once framed (opening + mat borders)
 *   board    mat / glass / backing cut size; extends under the frame lip
 *   rabbet   the groove in the moulding; board size + a little clearance
 *   outer    the outside of the finished frame
 * ------------------------------------------------------------------ */

function geometry(spec, rates) {
  const rules = rates.businessRules;
  const moulding = findBy(rates.mouldings, 'code', spec.mouldingCode);
  if (!moulding) throw new Error(`Unknown moulding: ${spec.mouldingCode}`);

  const mounting = findBy(rates.labour?.mounting, 'id', spec.mountingId);
  const matCount = MAT_COUNT[spec.matStyle] ?? 0;

  // Float mounting lifts the art off the backing, which needs a border of its
  // own when there's no mount board to provide one.
  const borderSides = matCount > 0 ? spec.matBorderSidesMm : (mounting?.floatBorderMm ?? 0);
  const borderBottom = matCount > 0 ? (spec.matBorderBottomMm ?? borderSides) : borderSides;

  // The shop charges on art + 2 x border exactly. No lip, clearance or overlap
  // deduction enters the price, however the pieces physically overlap.
  const boardW = spec.artWidthMm + 2 * borderSides;
  const boardH = spec.artHeightMm + borderSides + borderBottom;

  // The art tucks under the mount, so the hole cut in it is smaller than the
  // art. This only draws the preview; it never moves the price.
  const openingW = spec.artWidthMm - 2 * (matCount > 0 ? rules.artOverlapPerSideMm : 0);
  const openingH = spec.artHeightMm - 2 * (matCount > 0 ? rules.artOverlapPerSideMm : 0);

  const face = moulding.faceWidthMm;
  const outerW = boardW + 2 * face;
  const outerH = boardH + 2 * face;

  // The trade chop formula, and exactly what PriceMaster's job cards show:
  // each of the four mitres eats one face width at each end of a rail.
  const mouldingLengthMm = 2 * (boardW + boardH) + 8 * face;

  return {
    openingW, openingH,
    sightW: boardW, sightH: boardH,   // what shows inside the frame
    boardW, boardH,
    outerW, outerH,
    mouldingLengthMm,
    outerLongSideMm: Math.max(outerW, outerH),
    boardAreaM2: (boardW * boardH) / 1e6,
    moulding,
    mounting,
    matCount,
  };
}

/* ------------------------------------------------------------------ *
 * Stock sheets
 * ------------------------------------------------------------------ */

/** Can a w x h piece be cut from a w x h sheet, turning it if need be? */
function fitsSheet(pieceW, pieceH, sheetW, sheetH) {
  if (!sheetW || !sheetH) return true;   // no sheet size on record, so don't block
  return Math.max(pieceW, pieceH) <= Math.max(sheetW, sheetH)
    && Math.min(pieceW, pieceH) <= Math.min(sheetW, sheetH);
}

/** A glazing option can be stocked in several sheet sizes, each at its own rate. */
function glazingVariants(option) {
  return option?.variants?.length ? option.variants : [option];
}

/** The cheapest sheet the glass can be cut from, or null if none is big enough. */
function pickGlazingVariant(option, boardW, boardH) {
  const longSide = Math.max(boardW, boardH);
  return glazingVariants(option)
    .filter((v) => fitsSheet(boardW, boardH, v.sheetWidthMm, v.sheetHeightMm)
      && longSide <= (v.maxLongSideMm ?? Infinity))
    .sort((a, b) => a.sellPerM2ExVat - b.sellPerM2ExVat)[0] ?? null;
}

/**
 * A mount board comes in more than one sheet size. The shop calls them option A,
 * the standard sheet, and option B, a bigger one that costs more per square
 * metre. Same shape as glazing variants, and picked the same way.
 */
function matSheets(board) {
  return board?.sheets?.length ? board.sheets : [board];
}

/**
 * The cheapest sheet option for a board of this size, or null if it outgrows
 * them all. PriceMaster picks the option on the board's longest side alone,
 * not on whether the piece nests in the sheet: their own quotes charge option A
 * for a 1000 x 870 and an 880 x 980 board, both wider than an 815 mm sheet, and
 * only move to option B at 1110 mm long. So this is a size band, not a cutting
 * plan, and the shop knows how to get the piece out of the board.
 */
function pickMatSheet(board, boardW, boardH) {
  const longSide = Math.max(boardW, boardH);
  return matSheets(board)
    .filter((sheet) => longSide <= (sheet.maxBoardLongSideMm
      ?? (Math.max(sheet.sheetWidthMm ?? 0, sheet.sheetHeightMm ?? 0) || Infinity)))
    .sort((a, b) => a.sellPerM2ExVat - b.sellPerM2ExVat)[0] ?? null;
}

/** The biggest piece any of a board's sheets can yield, for the error message. */
function matMaxSheet(board) {
  const area = (s) => (s.sheetWidthMm ?? 0) * (s.sheetHeightMm ?? 0);
  return [...matSheets(board)].sort((a, b) => area(b) - area(a))[0];
}

function glazingMaxLongSide(option) {
  return Math.max(...glazingVariants(option).map((v) => v.maxLongSideMm ?? Infinity));
}

function largestVariant(option) {
  const area = (v) => (v.sheetWidthMm ?? 0) * (v.sheetHeightMm ?? 0);
  return [...glazingVariants(option)].sort((a, b) => area(b) - area(a))[0];
}

/* ------------------------------------------------------------------ *
 * Validation — the tab 1 scope gate, plus what stock sizes allow
 * ------------------------------------------------------------------ */

function validate(spec, rates) {
  const errors = [];
  const warnings = [];
  const scope = rates.scope;

  const longSide = Math.max(spec.artWidthMm, spec.artHeightMm);
  const shortSide = Math.min(spec.artWidthMm, spec.artHeightMm);
  const aspect = longSide / shortSide;

  if (longSide > scope.maxArtLongSideMm) {
    errors.push({
      code: 'OVERSIZE_LONG',
      message: `We quote online up to ${scope.maxArtLongSideMm}mm on the long side. Yours is ${Math.round(longSide)}mm.`,
      routeToConsultation: true,
    });
  }
  if (shortSide > scope.maxArtShortSideMm) {
    errors.push({
      code: 'OVERSIZE_SHORT',
      message: `We quote online up to ${scope.maxArtShortSideMm}mm on the short side. Yours is ${Math.round(shortSide)}mm.`,
      routeToConsultation: true,
    });
  }
  if (longSide < scope.minArtLongSideMm) {
    errors.push({
      code: 'UNDERSIZE',
      message: `Smallest we frame online is ${scope.minArtLongSideMm}mm on the long side.`,
      routeToConsultation: true,
    });
  }
  if (aspect > scope.maxAspectRatio + 1e-9) {
    errors.push({
      code: 'ASPECT',
      message: `That shape is more than ${scope.maxAspectRatio}:1. Panoramas need a person to look at them.`,
      routeToConsultation: true,
    });
  }

  // Everything below needs a frame we can lay out.
  const moulding = findBy(rates.mouldings, 'code', spec.mouldingCode);
  if (moulding && errors.length === 0) {
    const geo = geometry(spec, rates);

    if (geo.outerLongSideMm > moulding.maxLongSideMm) {
      errors.push({
        code: 'MOULDING_MAX',
        message: `${moulding.name} is not stable above ${moulding.maxLongSideMm}mm. Pick a heavier profile or a smaller size.`,
        routeToConsultation: false,
      });
    }

    const glazing = findBy(rates.glazing, 'code', spec.glazingCode);
    if (glazing && !pickGlazingVariant(glazing, geo.boardW, geo.boardH)) {
      errors.push({
        code: 'GLAZING_MAX',
        message: `${glazing.label} only goes up to ${glazingMaxLongSide(glazing)}mm. Choose a smaller size or different glass.`,
        routeToConsultation: false,
      });
    }

    const matCodes = new Set([spec.mat1Code, spec.mat2Code].slice(0, MAT_COUNT[spec.matStyle] ?? 0));
    for (const code of matCodes) {
      const board = findBy(rates.matBoards, 'code', code);
      if (board && !pickMatSheet(board, geo.boardW, geo.boardH)) {
        errors.push({
          code: 'MAT_TOO_BIG',
          message: `The largest ${board.colourName} sheet is ${matMaxSheet(board).sheetWidthMm} x ${matMaxSheet(board).sheetHeightMm}mm, too small for this frame. Try a narrower border or another mount.`,
          routeToConsultation: false,
        });
      }
    }
  }

  if (spec.printedByUs) {
    const paper = findBy(rates.printing, 'code', spec.printPaperCode);
    if (paper?.maxPrintLongSideMm && longSide > paper.maxPrintLongSideMm) {
      errors.push({
        code: 'PRINT_MAX',
        message: `${paper.label} prints up to ${paper.maxPrintLongSideMm}mm on the long side.`,
        routeToConsultation: false,
      });
    }
    if (spec.sourcePixels) {
      const dpi = effectiveDpi(spec.sourcePixels, spec.artWidthMm, spec.artHeightMm);
      const minDpi = paper?.minDpi ?? 150;
      if (dpi < minDpi * 0.75) {
        errors.push({
          code: 'DPI_TOO_LOW',
          message: `At this size and crop you're down to ${Math.round(dpi)} DPI. It will print soft. Zoom out, or choose a smaller size.`,
          routeToConsultation: false,
        });
      } else if (dpi < minDpi) {
        warnings.push({
          code: 'DPI_MARGINAL',
          message: `${Math.round(dpi)} DPI at this size and crop — acceptable, but zooming out or dropping a size would be sharper.`,
        });
      }
    }
  }

  return { ok: errors.length === 0, errors, warnings };
}

function effectiveDpi(pixels, widthMm, heightMm) {
  const dpiW = pixels.width / (widthMm / MM_PER_INCH);
  const dpiH = pixels.height / (heightMm / MM_PER_INCH);
  return Math.min(dpiW, dpiH);
}

/** Print sizes, from the catalogue, that still hit minDpi. */
function maxSizeForImage(pixels, printSizes, minDpi) {
  return printSizes.filter((s) => effectiveDpi(pixels, s.widthMm, s.heightMm) >= minDpi);
}

/* ------------------------------------------------------------------ *
 * Price
 * ------------------------------------------------------------------ */

/** A mount, backing or mounting rate, per square metre of board. */
function perM2(item) {
  // Older rate cards wrote these as { rateExVat, basis: 'm2' }.
  return item?.ratePerM2ExVat ?? (item?.basis === 'm2' ? item.rateExVat : 0) ?? 0;
}

/**
 * The full price breakdown for a spec, without checking that it's something we
 * quote online. The back-test uses this, so an out-of-scope job still gets a
 * number to compare. Customers only ever see priceQuote().
 */
function computePrice(spec, rates) {
  const rules = rates.businessRules;
  const labour = rates.labour ?? {};
  const geo = geometry(spec, rates);
  const area = geo.boardAreaM2;
  const lines = [];

  // --- Frame, by the metre ------------------------------------------
  const metres = geo.mouldingLengthMm / 1000;
  lines.push({
    group: 'Frame',
    label: geo.moulding.name,
    detail: `${metres.toFixed(3)} m at ${rand(geo.moulding.sellPerMExVat)}/m`,
    amount: metres * geo.moulding.sellPerMExVat,
  });

  // --- Mount board, by the area of the board ------------------------
  for (let i = 0; i < geo.matCount; i++) {
    const code = i === 0 ? spec.mat1Code : spec.mat2Code;
    const board = findBy(rates.matBoards, 'code', code);
    if (!board) throw new Error(`Unknown mat board: ${code}`);
    // A board too big for the standard sheet is cut from a larger, dearer one.
    const sheet = pickMatSheet(board, geo.boardW, geo.boardH) ?? matMaxSheet(board);
    const rate = sheet.sellPerM2ExVat;
    const sheetAreaM2 = (sheet.sheetWidthMm * sheet.sheetHeightMm) / 1e6;
    const chargeableM2 = Math.max(area, sheetAreaM2 * (sheet.minSheetFraction ?? board.minSheetFraction ?? 0));
    lines.push({
      group: 'Mount',
      label: `${board.colourName}${geo.matCount === 2 ? (i === 0 ? ' (top)' : ' (under)') : ''}`,
      detail: `${chargeableM2.toFixed(3)} m² at ${rand(rate)}/m²${sheet.label ? `, ${sheet.label} sheet` : ''}`,
      amount: chargeableM2 * rate,
    });
  }

  // --- Glass, twice over when floating ------------------------------
  const glazing = findBy(rates.glazing, 'code', spec.glazingCode);
  if (!glazing) throw new Error(`Unknown glazing: ${spec.glazingCode}`);
  const sheet = pickGlazingVariant(glazing, geo.boardW, geo.boardH) ?? largestVariant(glazing);
  const layers = geo.mounting?.glassLayers ?? 1;
  lines.push({
    group: 'Glazing',
    label: glazing.label,
    detail: `${area.toFixed(3)} m² at ${rand(sheet.sellPerM2ExVat)}/m²${layers > 1 ? ', glass both sides' : ''}`,
    amount: area * sheet.sellPerM2ExVat * layers,
  });

  // --- Printing, if we're printing the photo ------------------------
  if (spec.printedByUs) {
    const paper = findBy(rates.printing, 'code', spec.printPaperCode);
    if (!paper) throw new Error(`Unknown print paper: ${spec.printPaperCode}`);
    const printAreaM2 = (spec.artWidthMm * spec.artHeightMm) / 1e6;
    const raw = printAreaM2 * paper.sellPerM2ExVat;
    const amount = Math.max(raw, paper.minChargeExVat ?? 0);
    lines.push({
      group: 'Printing',
      label: paper.label,
      detail: amount > raw ? 'minimum charge' : `${printAreaM2.toFixed(3)} m² at ${rand(paper.sellPerM2ExVat)}/m²`,
      amount,
    });
  }

  // --- Backing and mounting, by the area of the board ---------------
  if (geo.mounting && perM2(geo.mounting) > 0) {
    lines.push({
      group: 'Workshop',
      label: geo.mounting.label,
      detail: `${area.toFixed(3)} m² at ${rand(perM2(geo.mounting))}/m²`,
      amount: area * perM2(geo.mounting),
    });
  }

  // --- The shop's flat "Extras": nylon string, hooks and fitting -----
  if (labour.fittingExVat) {
    lines.push({
      group: 'Workshop',
      label: labour.fittingLabel ?? 'Fitting and hardware',
      detail: 'per frame',
      amount: labour.fittingExVat,
    });
  }

  // --- Same-day rush, if they asked for it --------------------------
  if (spec.rushOrder && rules.rushFeeExVat > 0) {
    lines.push({ group: 'Workshop', label: 'Same-day rush', detail: 'jumped to the front of the queue', amount: rules.rushFeeExVat });
  }

  // --- Delivery -----------------------------------------------------
  const delivery = findBy(rates.delivery, 'id', spec.deliveryId);
  if (delivery && delivery.rateExVat > 0) {
    lines.push({ group: 'Delivery', label: delivery.label, detail: '', amount: delivery.rateExVat });
  }

  // --- An online markup, if the shop ever wants one ------------------
  // As its own line, not folded into the others: the customer is shown this
  // breakdown, and a breakdown that doesn't add up to its total is worse than
  // no breakdown. 0 means the website charges counter prices, which is what
  // the shop signed off.
  const markupPct = rules.onlineMarkupPct ?? 0;
  if (markupPct > 0) {
    const onParts = lines.reduce((sum, l) => sum + l.amount, 0);
    lines.push({
      group: 'Workshop',
      label: 'Online ordering',
      detail: `${markupPct}%`,
      amount: onParts * (markupPct / 100),
    });
  }

  // --- Totals -------------------------------------------------------
  let subtotalExVat = lines.reduce((sum, l) => sum + l.amount, 0);

  // The shop's minimum order is what the customer pays, so it is measured on the
  // total including VAT. Their own R458 quote stands, because R527 with VAT on
  // top already clears the R500 minimum.
  const vatRate = rules.vatRegistered ? rules.vatRatePct / 100 : 0;
  const minimum = rules.minOrderValueIncVat ?? rules.minOrderValueExVat ?? 0;
  let minimumApplied = false;
  if (subtotalExVat * (1 + vatRate) < minimum) {
    subtotalExVat = minimum / (1 + vatRate);
    minimumApplied = true;
  }

  const vat = subtotalExVat * vatRate;
  const totalIncVat = roundTo(subtotalExVat + vat, rules.roundToNearest);

  const range = rules.quoteMode === 'range'
    ? {
        low: roundTo(totalIncVat * (1 - rules.rangePct / 100), rules.roundToNearest),
        high: roundTo(totalIncVat * (1 + rules.rangePct / 100), rules.roundToNearest),
      }
    : null;

  return {
    geometry: geo,
    lines,
    subtotalExVat,
    vat,
    totalIncVat,
    range,
    minimumApplied,
    quoteMode: rules.quoteMode,
    validityDays: rules.quoteValidityDays,
    turnaroundWorkingDays: rules.turnaroundWorkingDays ?? null,
    placeholderPricing: rates._meta?.placeholder === true,
    validatedPricing: rates._meta?.validated === true,
  };
}

function priceQuote(spec, rates) {
  const check = validate(spec, rates);
  if (!check.ok) return { ok: false, ...check };
  return { ok: true, warnings: check.warnings, ...computePrice(spec, rates) };
}

/* ------------------------------------------------------------------ *
 * Helpers
 * ------------------------------------------------------------------ */

function findBy(list, key, value) {
  return list?.find((item) => item[key] === value);
}

const rand = (n) => `R${Number(n).toFixed(2)}`;

function roundTo(value, nearest) {
  if (!nearest) return Math.round(value * 100) / 100;
  return Math.round(value / nearest) * nearest;
}

function formatZar(amount) {
  return 'R' + Math.round(amount).toLocaleString('en-ZA');
}

/**
 * What the customer pays now, and what is left for collection day. The shop
 * starts work on a deposit; at 100% they simply pay in full.
 *
 * The rounding is deliberate: the deposit takes the odd cent, so the two halves
 * always add back to the total instead of leaving a cent unpaid.
 */
function splitDeposit(totalIncVat, rules) {
  const pct = Math.min(100, Math.max(1, Number(rules?.depositPct) || 100));
  const payNow = Math.ceil(totalIncVat * pct) / 100;
  return { pct, payNow, balance: Math.round((totalIncVat - payNow) * 100) / 100 };
}

/**
 * The same, but to the cent. For amounts we are about to charge: a button that
 * says R360 should not put R360,50 through the card.
 */
function formatZarExact(amount) {
  return 'R' + Number(amount).toLocaleString('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}


